// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address logger, address caller, bytes32 digest, uint256 utxo, bytes memory script, uint256 fee, bytes memory outpoint) internal {
        vm.assume(true);
        bool logResult = c.logRedemptionRequested(caller, digest, utxo, script, fee, outpoint);
        bool approved = c.approvedLoggers(logger);
        assertTrue(logger != caller || (approved == logResult));
    }

    function testFuzz_run(address logger, address caller, bytes32 digest, uint256 utxo, bytes memory script, uint256 fee, bytes memory outpoint) public {
        vm.assume(logger.code.length == 0 && uint160(logger) > 0xffff && logger != address(this) && logger != address(c) && logger != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logger != 0x000000000000000000636F6e736F6c652e6c6f67 && logger != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logger != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(logger, caller, digest, utxo, script, fee, outpoint);
    }
}
